-- Caso confirmado por el propietario; sólo contenido de guía, sin operaciones financieras.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('convenio-dos-hijos-800',$texto$Convenio de dos hijos y liquidación familiar: $480 + $320$texto$,'Cobranza',$texto$Sustituir dos adeudos de $600.00 y $400.00 por un acuerdo de $800.00 y liquidarlo con una transferencia familiar.$texto$,$texto$Dos inscripciones vigentes del mismo plantel y tutor responsable financiero, sin becas/recargos/abonos previos ni reportes en revisión. Cuenta bancaria activa compatible y acceso familiar financiero. Usuario administrativo persistido con permisos de conceptos, cuotas, adeudos, convenios, pagos y cuentas, además de Guía de procesos. Fechas del ejemplo dentro de inscripción/ciclo; reutilizar configuración ya creada sin duplicarla. Caso confirmado por el propietario; no ejecutar de nuevo sobre obligaciones reales sólo por consultar la guía.$texto$,$texto$Originales $600.00/$400.00, total $1,000.00; convenio $800.00, condonación $200.00; nuevos $480.00/$320.00. Una transferencia validada $800.00 deja banco B+$800.00, convenio Cumplido y nuevos saldos cero. Los originales permanecen Convenido y el tutor tiene comprobante.$texto$,1,DATE '2026-10-08','CONFIRMADA');

INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='convenio-dos-hijos-800';

INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('convenio-dos-hijos-800',1,$texto$Preparar conceptos independientes$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Conceptos de cobro. Busca CONV-ORIG-TEST y aplica filtros. 2. Si no existe, pulsa Nuevo registro: institución del ejemplo, código CONV-ORIG-TEST, nombre Adeudo original de prueba, categoría Otro y Activo Sí; deja becas, descuentos y recargos desactivados. Guarda con Crear concepto. 3. Repite para CONV-ACUERDO-TEST, nombre Convenio de pago de prueba, misma institución y sin ajustes. Si ya existe, verifica y reutiliza sin duplicarlo. 4. Comprueba que ambos conceptos están disponibles; no modifiques conceptos reales para reproducir este ejercicio.$texto$,$texto$Dos conceptos: origen y nuevo acuerdo.$texto$,$texto$Configuración separada, sin becas ni recargos.$texto$,$texto$Caso ilustrativo sobre inscripciones activas de dos hijos del mismo tutor y plantel.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('convenio-dos-hijos-800',2,$texto$Preparar cuota del primer hijo: $600$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. 2. Elige institución, plantel, inscripción del primer hijo y concepto CONV-ORIG-TEST. Configura Una sola vez, importe 600.00, moneda institucional y Estado Activa; marca Incluir en generación automática de cargos. 3. Captura Fecha límite de pago 20/10/2026 si pertenece a la inscripción y ciclo. En Configuración adicional verifica vigencia e inicio no posterior al corte de generación; adapta las fechas al rango válido si reproduces el caso otro día. 4. Pulsa Crear cuota; revisa Confirmar nueva cuota y pulsa Confirmar y crear cuota. Cancelar conserva la captura.$texto$,$texto$Primer hijo: cuota única $600.00.$texto$,$texto$Cuota guardada, todavía sin pago.$texto$,$texto$Si ya existe y generaste su cargo, reutiliza el adeudo; no crear otra cuota idéntica.$texto$,$texto$/admin/catalogos/cuotas-alumno$texto$),
('convenio-dos-hijos-800',3,$texto$Preparar cuota del segundo hijo: $400$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. 2. Elige inscripción del segundo hijo, mismo tutor financiero, institución y plantel; selecciona CONV-ORIG-TEST. 3. Configura Una sola vez, importe 400.00, Estado Activa, generación automática y fecha límite 20/10/2026 dentro de inscripción/ciclo; revisa vigencia como en la etapa anterior. 4. Pulsa Crear cuota → revisa el resumen → Confirmar y crear cuota. Comprueba que corresponde al segundo hijo.$texto$,$texto$Segundo hijo: cuota única $400.00.$texto$,$texto$Dos cuotas independientes suman $1,000.00.$texto$,$texto$Ambos alumnos deben tener al mismo tutor responsable financiero; este caso no mezcla planteles.$texto$,$texto$/admin/catalogos/cuotas-alumno$texto$),
('convenio-dos-hijos-800',4,$texto$Emitir solamente los dos adeudos originales$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos. Selecciona institución, plantel y corte válido de la prueba. 2. Pulsa Visualizar cuotas por aplicar. Usa Desmarcar todos y selecciona sólo las cuotas de $600.00 y $400.00; confirma beca $0.00 y total $1,000.00. 3. Pulsa Confirmar y generar adeudos seleccionados; en el modal comprueba dos registros y total, luego Confirmar y generar adeudos. Cancelar no genera ni limpia selección. 4. Regresa al listado de Adeudos, busca cada matrícula → Aplicar filtros → Ver → Resumen. Anota ambos números: abonos $0.00 y saldo $600.00/$400.00.$texto$,$texto$Dos cargos originales, total $1,000.00.$texto$,$texto$Deuda emitida sin movimiento de fondos.$texto$,$texto$Si ya existen estos adeudos, no volver a generarlos ni incluir otros registros de prueba.$texto$,$texto$/admin/catalogos/cargos$texto$),
('convenio-dos-hijos-800',5,$texto$Anotar el saldo bancario antes del convenio$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. 2. Busca la cuenta bancaria activa del mismo plantel o institucional compatible y pulsa Aplicar filtros. 3. Anota Saldo actual como B; el ejemplo usa B=$2,000.00, pero compara con el saldo real. 4. No edites el saldo inicial ni registres un ingreso manual: esta etapa sólo consulta.$texto$,$texto$B=$2,000.00 como referencia ilustrativa.$texto$,$texto$Cuenta destino y referencia B identificadas.$texto$,$texto$No confundir saldo inicial con saldo actual; separar movimientos de otras operaciones simultáneas.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('convenio-dos-hijos-800',6,$texto$Crear el convenio por $800$texto$,$texto$Administración$texto$,$texto$Convenios de pago$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago → Nuevo convenio. Selecciona institución, tutor responsable y Concepto del nuevo cargo CONV-ACUERDO-TEST. 2. En Buscar entre los cargos pendientes del tutor busca CONV-ORIG-TEST y pulsa Buscar. En Resultados disponibles pulsa Agregar únicamente en los originales de $600.00 y $400.00; verifica que Cargos agregados al convenio tiene dos registros y saldo $1,000.00. 3. Captura Fecha del acuerdo 08/10/2026, Nueva fecha límite 20/10/2026, Descripción que verá la familia Convenio de pago de dos hijos, Nuevo monto total 800.00 y Motivo del acuerdo Prueba controlada de convenio familiar con condonación de $200.00. Adapta fechas si reproduces otro día. 4. Pulsa Confirmar convenio; revisa tutor, selección $1,000.00, nuevo monto $800.00 y condonación $200.00. Cancelar conserva captura; Confirmar y crear convenio guarda el acuerdo.$texto$,$texto$Originales $600.00/$400.00; acuerdo $800.00; condonado $200.00.$texto$,$texto$Convenio creado sin ingresar dinero.$texto$,$texto$No incorporar cargos con pagos previos o transferencias en revisión en este ejemplo.$texto$,$texto$/admin/convenios-pago$texto$),
('convenio-dos-hijos-800',7,$texto$Revisar originales y nuevos cargos por hijo$texto$,$texto$Administración$texto$,$texto$Convenios y adeudos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca el tutor o folio del acuerdo → aplica filtros → Ver. 2. En Resumen verifica Saldo sustituido $1,000.00, Nuevo adeudo $800.00 y Monto condonado $200.00. 3. En Adeudos revisa originales conservados y nuevos cargos por alumno: $480.00 para quien debía $600.00 y $320.00 para quien debía $400.00, todavía pendientes. 4. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca cada matrícula → Aplicar filtros → Ver. Comprueba originales Convenido sin saldo exigible y nuevos con saldo $480.00/$320.00; anota números nuevos.$texto$,$texto$Distribución proporcional 60%/40% de $800.00.$texto$,$texto$Cada hijo conserva su obligación independiente y el origen histórico.$texto$,$texto$No canceles este convenio: la siguiente etapa prueba su liquidación. Cancelar se prueba con otro acuerdo sin pagos.$texto$,$texto$/admin/convenios-pago$texto$),
('convenio-dos-hijos-800',8,$texto$Reportar una transferencia familiar por ambos cargos$texto$,$texto$Tutor$texto$,$texto$Portal familiar → Tus pagos$texto$,$texto$1. Abre una ventana privada separada de administración, entra a /familias después de la dirección del sistema e inicia sesión con el tutor. Selecciona al hijo → Tus pagos → Reportar transferencia. 2. En Selecciona qué vas a pagar elige el cargo nuevo de $480.00; pulsa Agregar cargo y elige el de $320.00 del otro hijo. No deben duplicarse; total calculado y bloqueado $800.00. 3. Selecciona la cuenta bancaria anotada, fecha/hora que indique el comprobante y referencia TEST-CONVENIO-800. Adjunta el comprobante de prueba y revisa la sección 5 · Revisa y envía. 4. Pulsa Enviar transferencia a revisión. En Confirmar envío de transferencia comprueba ambos alumnos, importes, cuenta, fecha, referencia y archivos. Cancelar conserva todo sin enviar; Confirmar y enviar a revisión registra el reporte. Anota el folio y comprueba En revisión en el historial.$texto$,$texto$Una transferencia reportada $800.00, dos asignaciones $480.00/$320.00.$texto$,$texto$Reporte familiar guardado pendiente de revisión escolar.$texto$,$texto$Este formulario no realiza una transferencia bancaria. En operación real reportar sólo una transferencia realizada; no validar comprobantes ficticios fuera de una prueba controlada.$texto$,NULL),
('convenio-dos-hijos-800',9,$texto$Validar el único pago con las dos asignaciones$texto$,$texto$Administración$texto$,$texto$Pagos recibidos$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. Busca TEST-CONVENIO-800 o el folio anotado → Aplicar filtros → Ver. 2. En Detalle revisa total $800.00, referencia y comprobante; abre el archivo en otra pestaña para verificarlo. En Distribución comprueba $480.00 al primer cargo nuevo y $320.00 al segundo. 3. Abre Gestión; conserva la cuenta destino bancaria declarada y pulsa Validar y publicar. En Confirmar validación del pago revisa folio, total y cuenta; Cancelar no valida. 4. Si coincide, pulsa Confirmar validación y espera estado Validado. No registres un segundo pago ni una entrada financiera manual.$texto$,$texto$Un ingreso de $800.00 y dos abonos independientes.$texto$,$texto$Pago validado, con ingreso y aplicaciones publicados.$texto$,$texto$Usar usuario administrativo persistido autorizado, no acceso de recuperación. Validar únicamente dinero comprobado; esta guía describe el caso controlado confirmado.$texto$,$texto$/admin/catalogos/pagos$texto$),
('convenio-dos-hijos-800',10,$texto$Comprobar liquidación y comprobantes$texto$,$texto$Administración y tutor$texto$,$texto$Cuentas, adeudos, convenio y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca el banco → Aplicar filtros. Saldo actual debe ser B+$800.00; si B era $2,000.00 será $2,800.00, sin otras operaciones. 2. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca cada matrícula → Aplicar filtros → Ver → Resumen. Nuevos: total $480.00/$320.00, abonos respectivos completos y Falta por pagar $0.00; originales permanecen Convenido. 3. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Convenios de pago; busca folio → aplica filtros → Ver. Comprueba Cumplido y pendientes $0.00 en Adeudos. 4. En la ventana familiar entra a Tus pagos de cada hijo; no debe quedar esa deuda. En Tus pagos y comprobantes busca mes/año del pago → Buscar pagos y abre Ver comprobante PDF en otra pestaña. Conserva el historial; no repetir operaciones al leer esta guía.$texto$,$texto$Banco B+$800.00; deuda nueva $0.00 por ambos hijos; comprobante disponible.$texto$,$texto$Caso completo confirmado por el propietario el 08/10/2026.$texto$,$texto$No cancelar el convenio liquidado. La cancelación de un convenio sin pagos requiere otro caso independiente.$texto$,$texto$/admin/convenios-pago$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
